AGENT_INSTITUTION_CODE IN
#{regist.agentInstitutionCode,jdbcType=VARCHAR}
and PROD_REGIST_CODE IN
#{regist.prodRegistCode,jdbcType=VARCHAR}
) maxtime on his.CREATE_TIME=maxtime.CREATE_TIME
AGENT_INSTITUTION_CODE IN
