mapper.select:
select
a.REGIST_SEQNO registSeqno,
a.SEND_STATUS sendStatus,
a.SUBMIT_FEEDBACK_MSG submitFeedbackMsg,
a.SUBMIT_FEEDBACK_STATUS submitFeedbackStatus,
a.SUBMIT_TIME submitTime,
a.CHB_SUBMIT_DEADLINE chbSubmitDeadline,
a.SUBMIT_DEADLINE submitDeadline,
a.STATUS status,
a.AGENT_INSTITUTION_CODE agentInstitutionCode,
a.ISSUE_PARTY_ID issuePartyId,
a.PROD_ID prodId,
a.PROD_NAME prodName,
a.PROD_REGIST_CODE prodRegistCode,
a.SUMIT_SEQ sumitSeq,
a.DATA_DATE dataDate,
a.REMARK remark,
a.UPDATE_TIME
FROM
CHB_AGENT_PRD_SUB a
where 1=1

    and a.AGENT_INSTITUTION_CODE = #{agentInstitutionCode}


    and a.PROD_ID = #{prodId}


    and a.PROD_REGIST_CODE = #{prodRegistCode}


    and a.SUBMIT_FEEDBACK_STATUS = #{submitFeedbackStatus}


    and a.SEND_STATUS = #{sendStatus}



        #{status}



    and a.SUBMIT_DEADLINE between STR_TO_DATE(#{searchSubmitDeadlineStart,jdbcType=VARCHAR},'%Y-%m-%d')and STR_TO_DATE(#{searchSubmitDeadlineEnd,jdbcType=VARCHAR},'%Y-%m-%d')


    and DATE_FORMAT(a.DATA_DATE,'%Y-%m-%d')>= #{searchDataDateStart,jdbcType=VARCHAR}


    and DATE_FORMAT(a.DATA_DATE,'%Y-%m-%d')<= #{searchDataDateEnd,jdbcType=VARCHAR}


    and DATE_FORMAT(a.SUBMIT_TIME,'%Y-%m-%d')>= #{searchSubmitTimeStart,jdbcType=VARCHAR}


    and DATE_FORMAT(a.SUBMIT_TIME,'%Y-%m-%d')<= #{searchSubmitTimeEnd,jdbcType=VARCHAR}

ORDER BY AGENT_INSTITUTION_CODE DESC
